// The EGYCASH letterhead logo, as a data URI.
//
// It lives in its own file because it is ~60 KB of base64 and would drown any file it shared. It is
// carried over from the gold system byte for byte: this is what the printed receipts, handover
// slips and monthly statements have always shown at the top of the page, and a printed document is
// a company record — its letterhead is not a theme choice.
export const EGYCASH_LOGO =
  'data:image/png;base64,';
